# For each row, check if there's a pattern like "all non-zeros on left/right" or "scattered"
def row_pattern(arr):
    """Describe pattern of non-zeros per row"""
    patterns = []
    for r in range(arr.shape[0]):
        row = arr[r]
        nz_positions = [c for c, v in enumerate(row) if v != 0]
        if not nz_positions:
            patterns.append("empty")
        elif nz_positions[0] == 0:
            patterns.append("start +")
        elif nz_positions[-1] == arr.shape[1] - 1:
            patterns.append("end -")
        elif len(nz_positions) == 1:
            patterns.append("single")
        elif nz_positions[0] == len(nz_positions) - 1:
            patterns.append("consec")
        else:
            patterns.append("scat")
    return patterns

